codingChallenge.solution:
class Person:
    def __init__(self, name):
        self.name = name

class Student(Person):
    def __init__(self, name, grade):
        super().__init__(name)
        self.grade = grade

    def info(self):
        return f"Name: {self.name}, Grade: {self.grade}"

s = Student("Alex", 10)
print(s.info())

